---@class ExhibitData :私人家园展品数据
---@field serverID    @展示品serverID
---@field exhibitID   @展示品exhibitID
---@field articleID   @道具articleID
---@field exhibitType @展示品Type
---@field exhibitChildDic table<number,number> @展示品子节点<slot,serverID>
---@field slotTypeDic table<number,number> @展示品槽位可以存放的对应表 <slot,exhibitType>
---@field slotBoxSizeDic  table<number,string> @槽位盒子表 <slot,slotBox>
---@field slotNameDic table<number,string> @槽位挂点名 <slot,slotName>
---@field exhibitParentServerID @展品父节点id
---@field exhibitParentSlot @展品父节点slot
---@field exhibitBuilderId @展品BuilderId
ExhibitData = class("ExhibitData")

function ExhibitData:initialize(serverID,exhibitID,articleID)
    self.serverID = serverID
    self.exhibitID = exhibitID
    self.articleID = articleID
    self.exhibitChildDic={}
    self.slotTypeDic ={}
    self.slotBoxSizeDic ={}
    self.slotNameDic ={}
    self.exhibitBuilderId=-1
    self.exhibitParentSlot=-1
    self.exhibitParentServerID=-1
    if exhibitID>100 and exhibitID<107 then
        self.exhibitType = ExhibitType.PreviewCar
        return
    elseif exhibitID==100 then
        self.exhibitType = ExhibitType.Car
        return
    end
    ---@type dictexhibit_config_cell
    local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config, exhibitID)
    self.exhibitType = tonumber(cfgdata.type)
    local groups= stringSplit(cfgdata.childgroovegroup,':')
    for i =1, #groups do
        local key=tonumber( groups[i])
        if key>0 then
            self.exhibitChildDic[key]=-1
            ---@type dictpersonalhomeslot_config_cell
            local cfgslotdata = CommonHelper:GetTableDataByID(ConfigNames.dictpersonalhomeslot_config,key)
            if cfgslotdata==nil  then
                logError("  槽位表没有该id：  ",key)
            else
                local sizeList= stringSplit(cfgslotdata.box_size,':')
                self.slotBoxSizeDic[key] = Vector3( tonumber(sizeList[1]),tonumber(sizeList[2]),tonumber(sizeList[3]))
                self.slotNameDic[key] = cfgslotdata.point
                self.slotTypeDic[key] = tonumber(cfgslotdata.type)
            end
        end
    end
end

function ExhibitData:CheckCanPutIn(slot,type)
    if self.slotTypeDic and self.slotTypeDic[slot]==type then
        return true
    end
    return false
end

function ExhibitData:GetArticleID() return self.articleID end

function ExhibitData:GetServerID() return self.serverID end

function ExhibitData:GetExhibitID() return self.exhibitID end

function ExhibitData:GetSlotNameDic() return self.slotNameDic end

function ExhibitData:GetSlotBoxSizeDic() return self.slotBoxSizeDic end

function ExhibitData:GetSlotTypeDic() return self.slotTypeDic end

function ExhibitData:GetType() return self.exhibitType end

function ExhibitData:GetChildDic() return self.exhibitChildDic end

function ExhibitData:GetChildServerIdBySlot(slot) return self.exhibitChildDic[slot] end

function ExhibitData:GetExhibitBuilderId() return self.exhibitBuilderId end

function ExhibitData:SetExhibitBuilderId(exhibitBuilderId)  self.exhibitBuilderId=exhibitBuilderId end

---@param slot number
---@param serverID number
function ExhibitData:SetChild(slot,serverID)  self.exhibitChildDic[slot]=serverID end

function ExhibitData:SetParentInfo(id,slot)
    self.exhibitParentServerID =id
    self.exhibitParentSlot=slot
end

function ExhibitData:GetParentInfo()
    return self.exhibitParentServerID,self.exhibitParentSlot
end

function ExhibitData:GetParentServerID()
    return self.exhibitParentServerID
end

function ExhibitData:GetParentSlot()
    return self.exhibitParentSlot
end

---@return PersonalHomeMapNode
function ExhibitData:GetPersonalHomeMapNode()
    ---@type PersonalHomeMapNode
    local nodeData =  {
        ID = self.exhibitID,
        ServerID = self.serverID,
        ChildDic={}
    }
    for slot,childId in pairs(self.exhibitChildDic) do
        if childId>0 then
            local childExhibit = PersonalHomeDataManager:Get():GetExhibitByServerID(childId)
            table.insert(nodeData.ChildDic, {SlotID=slot,ChildServerID=childId,ExhibitID=childExhibit:GetExhibitID()})
        end
    end
    return nodeData
end



